using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using UnityEngine.Rendering.HighDefinition;
public static class SolidTreeMeshFactory {
 public const string Folder="Assets/NewMap/FiveHangars/SolidTreeShapes";
 static Material material;static Dictionary<string,Mesh> cache=new Dictionary<string,Mesh>();
 public static Material Material {get{if(material)return material;var texture=new Texture2D(16,2,TextureFormat.RGBA32,false,true){name="Solid tree colour palette",filterMode=FilterMode.Point,wrapMode=TextureWrapMode.Clamp};Color[] colours={new Color(.16f,.29f,.045f),new Color(.21f,.35f,.065f),new Color(.25f,.4f,.08f),new Color(.29f,.44f,.1f),new Color(.2f,.34f,.05f),new Color(.27f,.39f,.065f),new Color(.31f,.45f,.105f),new Color(.24f,.36f,.055f),new Color(.23f,.105f,.035f),new Color(.29f,.15f,.055f),new Color(.34f,.19f,.075f),new Color(.26f,.125f,.04f),new Color(.16f,.29f,.045f),new Color(.2f,.34f,.06f),new Color(.25f,.4f,.085f),new Color(.29f,.43f,.1f)};for(int y=0;y<2;y++)for(int x=0;x<16;x++)texture.SetPixel(x,y,colours[x]);texture.Apply();AssetDatabase.CreateAsset(texture,Folder+"/Solid tree palette.asset");material=new Material(Shader.Find("HDRP/Lit")){name="Solid low poly tree palette",enableInstancing=true};material.SetTexture("_BaseColorMap",texture);material.SetColor("_BaseColor",Color.white);material.SetFloat("_Smoothness",.12f);material.SetFloat("_AlphaCutoffEnable",1);material.SetFloat("_AlphaCutoff",.5f);HDMaterial.ValidateMaterial(material);AssetDatabase.CreateAsset(material,Folder+"/Solid low poly tree palette.mat");return material;}}
 sealed class Builder {public List<Vector3> v=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> tris=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 c,int colour){int n=v.Count;v.Add(a);v.Add(b);v.Add(c);var t=new Vector2((colour+.5f)/16,.5f);uv.Add(t);uv.Add(t);uv.Add(t);tris.Add(n);tris.Add(n+1);tris.Add(n+2);}public void Tube(Vector3 a,Vector3 b,float ra,float rb,int sides){var rotation=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);for(int i=0;i<sides;i++){float x=i*Mathf.PI*2/sides,y=(i+1)*Mathf.PI*2/sides;var p=a+rotation*new Vector3(Mathf.Cos(x)*ra,0,Mathf.Sin(x)*ra);var q=a+rotation*new Vector3(Mathf.Cos(y)*ra,0,Mathf.Sin(y)*ra);var r=b+rotation*new Vector3(Mathf.Cos(x)*rb,0,Mathf.Sin(x)*rb);var s=b+rotation*new Vector3(Mathf.Cos(y)*rb,0,Mathf.Sin(y)*rb);Tri(p,r,q,8+i%4);Tri(q,r,s,8+i%4);Tri(a,q,p,8+i%4);Tri(b,r,s,8+i%4);}}
 public void Crown(Vector3 center,Vector3 radius,int sides,int rings,int seed){Func<int,int,Vector3> point=(ring,side)=>{float latitude=Mathf.PI*(ring+1)/(rings+1),angle=side*Mathf.PI*2/sides;float wobble=1+.055f*Mathf.Sin(side*2.3f+ring*1.7f+seed);return center+Vector3.Scale(radius,new Vector3(Mathf.Cos(angle)*Mathf.Sin(latitude)*wobble,Mathf.Cos(latitude),Mathf.Sin(angle)*Mathf.Sin(latitude)*wobble));};for(int s=0;s<sides;s++){int next=(s+1)%sides;Tri(center+Vector3.up*radius.y,point(0,next),point(0,s),(s+seed)%8);for(int r=0;r<rings-1;r++){Tri(point(r,s),point(r,next),point(r+1,s),(s+r+seed)%8);Tri(point(r,next),point(r+1,next),point(r+1,s),(s+r+seed)%8);}Tri(center-Vector3.up*radius.y,point(rings-1,s),point(rings-1,next),(s+seed)%8);}}}
 public static Mesh Get(GameObject model,int detail){detail=Mathf.Clamp(detail,0,2);string key=model.name+" Solid LOD"+detail;if(cache.TryGetValue(key,out var existing))return existing;var rs=model.GetComponentInChildren<LODGroup>().GetLODs()[0].renderers;var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);float h=Mathf.Max(3.4f,bounds.max.y),w=bounds.size.x,d=bounds.size.z;var b=new Builder();int sides=detail==0?8:detail==1?7:5,rings=detail==0?4:detail==1?3:2;float thickness=Mathf.Max(.12f,w*.052f);b.Tube(Vector3.zero,new Vector3(.03f*w,.55f*h,0),thickness,thickness*.43f,detail==2?4:6);var centres=new[]{new Vector3(0,.75f*h,0),new Vector3(-.21f*w,.67f*h,0),new Vector3(.21f*w,.66f*h,.02f*d),new Vector3(0,.64f*h,-.21f*d),new Vector3(.02f*w,.6f*h,.22f*d),new Vector3(0,.88f*h,0),new Vector3(-.08f*w,.51f*h,.08f*d)};int count=detail==0?7:detail==1?6:4;for(int i=0;i<count;i++){var radius=i==5?new Vector3(w*.24f,h*.15f,d*.24f):i==6?new Vector3(w*.25f,h*.19f,d*.25f):new Vector3(w*.285f,h*.235f,d*.28f);b.Crown(centres[i],radius,sides,rings,i*3+model.name.Length);if(i>0&&i<4)b.Tube(new Vector3(.02f*w,.32f*h,0),centres[i],thickness*.56f,thickness*.18f,detail==2?3:4);}var mesh=new Mesh{name=key,indexFormat=IndexFormat.UInt32};mesh.SetVertices(b.v);mesh.SetUVs(0,b.uv);mesh.SetTriangles(b.tris,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Folder+"/"+key+".asset");cache.Add(key,mesh);return mesh;}
}
